structureCode.vanilla:
const group = createInputGroup({ 'aria-label': 'Endereço do site' });

const prefix = createInputGroupAddon({ align: 'inline-start' });
prefix.appendChild(createInputGroupText({ text: 'https://' }));

const field = createInputGroupInput({ placeholder: 'minhaempresa' });

const suffix = createInputGroupAddon({ align: 'inline-end' });
suffix.appendChild(createInputGroupButton({ label: 'Colar', onClick: paste }));

group.append(prefix, field, suffix);

extensibilityCode.react:
// O grupo repassa todo atributo nativo de <div>, e o campo todo atributo
// de <input>. O estado inválido é do CAMPO — a moldura reage por :has().
<InputGroup aria-label="Endereço do site">
  <InputGroupInput
    aria-invalid={hasError}
    aria-describedby={hasError ? "site-error" : undefined}
  />
</InputGroup>
<p id="site-error">Endereço inválido</p>

extensibilityCode.vanilla:
// As fábricas devolvem o elemento nativo: o que falta se escreve nele.
// O estado inválido é do CAMPO — a moldura reage por :has().
const field = createInputGroupInput({ id: 'site' });
field.setAttribute('aria-invalid', 'true');
field.setAttribute('aria-describedby', 'site-error');

customizationCode.web:
/* A moldura lê os tokens do tema — trocar o tema troca o grupo inteiro.
   Para um caso pontual, sobreponha o token no escopo, nunca a cor na regra. */
.formulario-de-busca .nds-input-group {
  --radius: var(--radius-full);
}

